using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

public class A5_F3_ExcludeFromCodeCoverageAllKindsTests
{
    private const string Source = @"
using MessagePack;

namespace TestNs
{
    public enum MyEnum { A, B, C }

    [MessagePackObject]
    public class MyObject
    {
        [Key(0)] public int Value { get; set; }
        [Key(1)] public MyEnum EnumValue { get; set; }
        [Key(2)] public MyGeneric<int> Generic { get; set; }
        [Key(3)] public IMyUnion Union { get; set; }
    }

    [MessagePackObject]
    public class MyGeneric<T>
    {
        [Key(0)] public T Item { get; set; }
    }

    [Union(0, typeof(UnionA))]
    [Union(1, typeof(UnionB))]
    public interface IMyUnion { }

    [MessagePackObject]
    public class UnionA : IMyUnion { [Key(0)] public int A { get; set; } }

    [MessagePackObject]
    public class UnionB : IMyUnion { [Key(0)] public string B { get; set; } }
}
";

    [Fact]
    public void A5_F3_AllGeneratedTypesCarryExcludeFromCodeCoverage()
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        SyntaxTree userTree = CSharpSyntaxTree.ParseText(Source, parseOptions, path: "UserCode.cs");

        CSharpCompilation compilation = CSharpCompilation.Create(
            "A5F3TestAssembly",
            new[] { userTree },
            GetReferences(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        List<ISourceGenerator> generators = GetGenerators();
        Assert.NotEmpty(generators);

        GeneratorDriver driver = CSharpGeneratorDriver.Create(generators, parseOptions: parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);

        HashSet<SyntaxTree> originalTrees = new HashSet<SyntaxTree>(compilation.SyntaxTrees);
        List<SyntaxTree> generatedTrees = output.SyntaxTrees.Where(t => !originalTrees.Contains(t)).ToList();
        Assert.NotEmpty(generatedTrees);

        List<string> generatedTypeNames = new List<string>();
        List<string> missing = new List<string>();

        foreach (SyntaxTree tree in generatedTrees)
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (TypeDeclarationSyntax decl in tree.GetRoot().DescendantNodes().OfType<TypeDeclarationSyntax>())
            {
                if (decl is InterfaceDeclarationSyntax)
                {
                    continue;
                }

                INamedTypeSymbol? symbol = model.GetDeclaredSymbol(decl) as INamedTypeSymbol;
                if (symbol is null)
                {
                    continue;
                }

                // Skip user types that the generator may extend with partial declarations.
                if (symbol.DeclaringSyntaxReferences.Any(r => originalTrees.Contains(r.SyntaxTree)))
                {
                    continue;
                }

                string name = symbol.ToDisplayString();
                generatedTypeNames.Add(name);

                if (!IsCovered(symbol))
                {
                    missing.Add(name);
                }
            }
        }

        Assert.NotEmpty(generatedTypeNames);
        Assert.Contains(generatedTypeNames, n => n.IndexOf("Formatter", StringComparison.Ordinal) >= 0);
        Assert.Contains(generatedTypeNames, n => n.IndexOf("Resolver", StringComparison.Ordinal) >= 0);
        Assert.True(
            missing.Count == 0,
            "Generated types without ExcludeFromCodeCoverage: " + string.Join(", ", missing.Distinct()));
    }

    private static bool IsCovered(INamedTypeSymbol symbol)
    {
        for (INamedTypeSymbol? current = symbol; current is not null; current = current.ContainingType)
        {
            if (HasAttribute(current))
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasAttribute(INamedTypeSymbol symbol)
    {
        foreach (AttributeData attr in symbol.GetAttributes())
        {
            string? attrName = attr.AttributeClass?.Name;
            if (attrName is not null && attrName.IndexOf("ExcludeFromCodeCoverage", StringComparison.Ordinal) >= 0)
            {
                return true;
            }
        }

        foreach (SyntaxReference reference in symbol.DeclaringSyntaxReferences)
        {
            if (reference.GetSyntax() is MemberDeclarationSyntax member)
            {
                foreach (AttributeListSyntax list in member.AttributeLists)
                {
                    foreach (AttributeSyntax attribute in list.Attributes)
                    {
                        if (attribute.Name.ToString().IndexOf("ExcludeFromCodeCoverage", StringComparison.Ordinal) >= 0)
                        {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    }

    private static List<ISourceGenerator> GetGenerators()
    {
        Type[] types;
        try
        {
            types = typeof(FullModel).Assembly.GetTypes();
        }
        catch (ReflectionTypeLoadException ex)
        {
            types = ex.Types.Where(t => t is not null).Select(t => t!).ToArray();
        }

        List<ISourceGenerator> result = new List<ISourceGenerator>();
        foreach (Type t in types)
        {
            if (t.IsAbstract || t.IsGenericTypeDefinition || t.GetConstructor(Type.EmptyTypes) is null)
            {
                continue;
            }

            if (typeof(IIncrementalGenerator).IsAssignableFrom(t))
            {
                result.Add(((IIncrementalGenerator)Activator.CreateInstance(t)!).AsSourceGenerator());
            }
            else if (typeof(ISourceGenerator).IsAssignableFrom(t))
            {
                result.Add((ISourceGenerator)Activator.CreateInstance(t)!);
            }
        }

        return result;
    }

    private static IEnumerable<MetadataReference> GetReferences()
    {
        Dictionary<string, string> paths = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        void Add(string? location)
        {
            if (string.IsNullOrEmpty(location) || !File.Exists(location))
            {
                return;
            }

            string fileName = Path.GetFileName(location!);
            if (!paths.ContainsKey(fileName))
            {
                paths[fileName] = location!;
            }
        }

        Add(typeof(MessagePack.MessagePackObjectAttribute).Assembly.Location);
        Add(typeof(MessagePack.Formatters.IMessagePackFormatter<>).Assembly.Location);
        Add(typeof(object).Assembly.Location);

        if (AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string p in tpa.Split(new[] { Path.PathSeparator }, StringSplitOptions.RemoveEmptyEntries))
            {
                Add(p);
            }
        }

        foreach (Assembly asm in AppDomain.CurrentDomain.GetAssemblies())
        {
            if (asm.IsDynamic)
            {
                continue;
            }

            string? location;
            try
            {
                location = asm.Location;
            }
            catch (NotSupportedException)
            {
                continue;
            }

            Add(location);
        }

        return paths.Values.Select(p => (MetadataReference)MetadataReference.CreateFromFile(p)).ToList();
    }
}
